<?php
namespace App\Repositories;
use App\Models\Job; use App\Repositories\Contracts\JobRepositoryInterface; use Illuminate\Contracts\Pagination\LengthAwarePaginator;
class EloquentJobRepository implements JobRepositoryInterface { public function paginatePublished(array $filters=[],int $perPage=12):LengthAwarePaginator{$query=Job::query()->with(['company.user','category'])->withCount('applications')->where('status','published');$search=$filters['search']??null;if($search!==null&&$search!==''){$query->where(fn($q)=>$q->where('title','like',"%{$search}%")->orWhere('location','like',"%{$search}%"));}$category=$filters['category']??null;if($category!==null&&$category!==''){$query->where('job_category_id',$category);}$location=$filters['location']??null;if($location!==null&&$location!==''){$query->where('location','like',"%{$location}%");}$minRate=$filters['min_rate']??null;if($minRate!==null&&$minRate!==''){$query->where('daily_rate','>=',(float) $minRate);}$maxRate=$filters['max_rate']??null;if($maxRate!==null&&$maxRate!==''){$query->where('daily_rate','<=',(float) $maxRate);}return $query->latest()->paginate($perPage)->withQueryString();} public function create(array $data):Job{return Job::create($data);} public function update(Job $job,array $data):Job{$job->update($data);return $job->refresh();} public function delete(Job $job):void{$job->delete();} }
